#include "can_v_usr_private.h"
#ifdef DEV_LPC_236x
	#include "nvram_usr.h"
#endif

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

static Boolean init_error 				(void) ;

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

Boolean can_v_usr_init_nvfs (void)
{
  return(init_error()) ;
}

//--------------------------------------------------------------------------//

static Boolean init_error (void)
{
  UInt16 size = 0 ;

  if(nvfs_rd_size(nvfs_can_v_usr_err , &size) == NVFS_OK)
    {
	  if(size == sizeof (can_v_usr_err))
        {
		  if (nvfs_rd_s(nvfs_can_v_usr_err , &can_v_usr_err, sizeof(can_v_usr_err)) == NVFS_OK)
		    {		  	 
			  return TRUE ;
		    }	 
        }
    }  
  
  nvfs_delete(nvfs_can_v_usr_err) ;

  if (nvfs_wr_create (nvfs_can_v_usr_err, &can_v_usr_err , sizeof (Can_V_Usr_Error)) == NVFS_OK)
    {
	  return init_error() ;   
    }      
  return FALSE ;
}


